			                var 敏捷提高 =Math.floor(Math.random()*(最大属性值-最小属性值))+最小属性值;
			                var 智力提高 =Math.floor(Math.random()*(最大属性值-最小属性值))+最小属性值;
			                var 运气提高 =Math.floor(Math.random()*(最大属性值-最小属性值))+最小属性值;
			                var 物攻提高 =Math.floor(Math.random()*(最大属性值-最小属性值))+最小属性值;
			                var 魔攻提高 =Math.floor(Math.random()*(最大属性值-最小属性值))+最小属性值;
							当前力量 = item.getStr ();
			                当前敏捷 = item.getDex ();
			                当前智力 = item.getInt ();
			                当前运气 = item.getLuk ();
